  static const std::set<std::string> supported{"Name","InheritFrom","FilePath","Type","VisualFx","VisualFxManagerCap","AngleFromOwner","AngleMax","AngleMin","EaseOut","EndFrame","NumFrames","RandomDurationMax","RandomDurationMin","StartFrame","RandomOffsetX","RandomOffsetY","LocationFromOwner","VelocityMax","VelocityMin","RandomRotation","RandomRotationSpeedMax","RandomRotationSpeedMin","PingPongScale","ScaleMax","ScaleMin","StartScale","Ambient","VisualFxCap","VisualFxIntervalMax","VisualFxIntervalMin","OnlyWhenVisible","EndOffsetY","EndScale"};
