 static const std::set<std::string> fields{"Name","InheritFrom","Type","FilePath","AngleChangeAcceleration","AngleChangeSpeedMax","AngleChangeSpeedMin","AngleFromOwner","EaseOut","EndFrame","NumFrames","RandomPlaySpeedMax","RandomPlaySpeedMin","StartFrame","EndOffsetY","OffsetZ","RandomOffsetX","RandomOffsetY","LocationFromOwner","LocationZFromOwner","SortMode","SortFromOwner","GroupName","Acceleration","Gravity","VelocityMax","VelocityMin","RandomRotation","RandomRotationSpeedMax","RandomRotationSpeedMin","ScaleMax","ScaleMin","Ambient","CancelOverCap","OnlyWhenVisible","Slides","Angle","ClearSlides","EndScale","StartScale"};
