 const auto& d=definition(name);EffectParticleState p;p.name=name;p.sourceDefinition=d;p.source=request.source;p.ownerId=owner.lifetime?request.ownerId:0;p.ownerLifetime=owner.lifetime;p.imageBank=imageBankFor(name);p.imageClip=*p.imageBank->find(name);p.constant=true;p.durationBound=true;p.ownerScale=owner.scale;p.x=request.position[0];p.y=request.position[1];p.baseZ=request.distance?request.position[2]:source.location[2];p.offsetZ=source.definition->offsetZ;p.startScale=field(d,"StartScale",1);p.endScale=field(d,"EndScale",1);
