bool EffectParticleWorld::createEmber(const std::string& name,const EffectSpawnRequest& request,const EffectAnimationEntity& source,const EffectOwnerState& owner,const EffectParticleAdmission& admission,const EffectAnimationRandom& random,uint64_t& handle,std::string& error){
 const auto& d=definition(name);EffectParticleState p;p.name=name;p.sourceDefinition=d;p.source=request.source;p.ownerId=request.ownerId;p.ownerLifetime=owner.lifetime;p.imageBank=imageBankFor(name);p.imageClip=*p.imageBank->find(name);p.constant=true;p.durationBound=true;p.ownerScale=owner.scale;p.x=request.position[0];p.y=request.position[1];p.baseZ=request.distance?request.position[2]:source.location[2];p.offsetZ=source.definition->offsetZ;p.startScale=field(d,"StartScale",1);p.endScale=field(d,"EndScale",1);p.pingPongScale=d.get("PingPongScale")&&d.get("PingPongScale")->boolean();p.endOffsetY=field(d,"EndOffsetY");p.easeOut=field(d,"EaseOut");p.sourceColorResolved=true;
 AnimationAllocation allocation;allocation.name=name;allocation.sourceDefinition=d;allocation.type=NativeAnimationType::Constant;allocation.ownership=AnimationOwnership::ManagerCreate;allocation.ownerId=p.ownerId;allocation.ownerLifetime=p.ownerLifetime;allocation.manager=registry_->find(source.handle)->manager;allocation.onlyWhenVisible=true;
 if(!registry_->allocate(allocation,p.handle,error))return false;
 float value=0;
 if(!uniform(random,field(d,"RandomDurationMin"),field(d,"RandomDurationMax"),p.duration,error)||!uniform(random,field(d,"ScaleMin"),field(d,"ScaleMax"),p.ownScale,error)||!uniform(random,radians(field(d,"AngleMin")),radians(field(d,"AngleMax")),p.heading,error)||!uniform(random,field(d,"VelocityMin"),field(d,"VelocityMax"),p.speed,error)||!uniform(random,radians(field(d,"RandomRotationSpeedMin")),radians(field(d,"RandomRotationSpeedMax")),p.rotationSpeed,error)||!uniform(random,0,std::bit_cast<float>(0x40c90fdbu),p.rotation,error))return false;
 // Native zero RandomOffset fields skip their separate random branches.
 if(field(d,"RandomOffsetX")!=0){if(!uniform(random,-field(d,"RandomOffsetX"),field(d,"RandomOffsetX"),value,error))return false;p.x+=value;}
 if(field(d,"RandomOffsetY")!=0){if(!uniform(random,-field(d,"RandomOffsetY"),field(d,"RandomOffsetY"),value,error))return false;p.y+=value;}
 p.durationRemaining=p.duration;p.heading=addAngle(p.heading,owner.angle);
 if(text(d,"VisualFx")=="TartarusEmber01B"){
  p.componentWorld=admission.componentWorld;
  if(!p.componentWorld->attachParticleSpawner(p.handle,name,{p.x,p.y,p.baseZ},drawOwnScale(p),p.ownerScale,p.heading,p.duration,random,error))return false;
 }
 if(!registry_->commitInitialization(p.handle,false,error))return false;std::optional<uint64_t> victim;if(!registry_->addToManager(p.handle,*admission.permanentVfxCap,victim,error))return false;
 p.ownScale*=source.ownScale*owner.scale;p.heading=addAngle(p.heading,request.nativeAngle);p.heading=addAngle(p.heading,source.angle);p.modifiedTime=admission.sourceModifiedTime;p.timeModifierFraction=admission.sourceTimeModifierFraction;if(*admission.ownerTimeModifierFraction!=1){p.modifiedTime=0;p.timeModifierFraction=admission.ownerTimeModifierFraction;}
 if(p.componentWorld&&!p.componentWorld->syncParticleSpawner(p.handle,{p.x,p.y,p.baseZ},drawOwnScale(p),p.ownerScale,p.heading,p.durationRemaining,false,error))return false;
 handle=p.handle;particles_.emplace(p.handle,std::move(p));return true;
}
bool EffectParticleWorld::alive(uint64_t handle)const{auto p=particles_.find(handle);const auto* entry=registry_?registry_->find(handle):nullptr;return p!=particles_.end()&&!p->second.done&&entry&&!entry->canceled;}
bool EffectParticleWorld::refreshOwners(const EffectOwnerProvider& owners,std::string& error){try{if(mutating_||faulted_||!owners){error="Actual native particle owner lookup unavailable/reentrant";return false;}Guard guard(mutating_);std::vector<std::pair<uint64_t,float>> plan;for(const auto& [id,p]:particles_){if(!alive(id))continue;EffectOwnerState owner;if(!owners(p.ownerId,owner,error))return false;if(owner.lifetime!=p.ownerLifetime||!std::isfinite(owner.scale)||owner.scale<0){error="Actual particle owner lifetime/body scale unavailable";return false;}plan.emplace_back(id,p.inheritOwnerScale?owner.scale:1);}for(const auto& [id,scale]:plan)particles_.at(id).ownerScale=scale;return true;}catch(const std::exception& ex){error=ex.what();return false;}}
bool EffectParticleWorld::syncSpawners(std::string& error){if(mutating_||faulted_){error=faulted_?fault_:"Reentrant particle spawner synchronization";return false;}for(const auto& [id,p]:particles_)if(p.componentWorld){const float own=drawOwnScale(p);if(!p.componentWorld->syncParticleSpawner(id,{p.x,p.y,p.baseZ},own,p.ownerScale,p.heading,p.durationRemaining,!alive(id),error))return false;}return true;}
size_t EffectParticleWorld::liveCount()const{size_t n=0;for(const auto& [id,p]:particles_){(void)p;n+=alive(id);}return n;}
void EffectParticleWorld::disposeDone(){if(mutating_)throw std::runtime_error("Reentrant native particle disposal");std::vector<uint64_t> disposed;for(const auto& [id,p]:particles_){const auto* a=registry_?registry_->find(id):nullptr;if(p.done||(a&&a->canceled))disposed.push_back(id);}for(auto id:disposed){std::string error;auto& p=particles_.at(id);if(p.sound){if(!p.stopSound||!p.stopSound(p.sound,field(p.sourceDefinition,"StopSoundOnFinishFade"),error))throw std::runtime_error("Native particle sound disposal: "+error);p.sound=0;}if(p.componentWorld&&!p.componentWorld->detachParticleSpawner(id,error))throw std::runtime_error(error);if(!registry_->dispose(id,error))throw std::runtime_error(error);particles_.erase(id);}}
float EffectParticleWorld::interpolate(float a,float b,float t,float in,float out){if(in>0||out>0){const float rest=1-t,t2=t*t,rest2=rest*rest;const float v=float(double(((3*in)*t)*rest2)+double(((3*out)*t2)*rest)+double(t2*t));return (b-a)*v+a;}return (b-a)*t+a;}
float EffectParticleWorld::drawOwnScale(const EffectParticleState& p){float transition=1;if(p.startScale!=p.endScale){const float t=p.animationFraction;if(p.pingPongScale)transition=t<.5f?interpolate(p.startScale,p.endScale,t*2,p.easeIn,p.easeOut):interpolate(p.endScale,p.startScale,(t-.5f)*2,p.easeIn,p.easeOut);else transition=interpolate(p.startScale,p.endScale,t,p.easeIn,p.easeOut);}return p.ownScale*transition;}
float EffectParticleWorld::drawScale(const EffectParticleState& p){return drawOwnScale(p)*p.ownerScale;}
float EffectParticleWorld::drawOffsetY(const EffectParticleState& p){return p.ownerScale*(p.offsetY+(p.startOffsetY==p.endOffsetY?0:interpolate(p.startOffsetY,p.endOffsetY,p.animationFraction,p.easeIn,p.easeOut)));}
bool EffectParticleWorld::phase(EffectParticlePhase phase,float seconds,const EffectBoundedRandom& random,std::string& error){
 try{if(mutating_||faulted_){error=faulted_?fault_:"Reentrant particle phase";return false;}if(!std::isfinite(seconds)||seconds<0||seconds>1){error="Original particle modified time outside bounds";return false;}if(phase==EffectParticlePhase::SlidePostUpdate&&!random){error="Actual PCG needed before slide update";return false;}if(!registry_){error="Actual particle registry unavailable before phase";return false;}for(const auto& [id,p]:particles_){const auto* entry=registry_->find(id);if(!entry){error="Actual particle lifetime disposed outside owner phase";return false;}if(entry->canceled)continue;if(!p.done&&(p.modifiedTime||(p.timeModifierFraction&&*p.timeModifierFraction!=1))){error="Per-entity modified time component requires original time-system adapter before phase mutation";return false;}}mutating_=true;
  for(auto& [id,p]:particles_){if(p.done||registry_->find(id)->canceled)continue;switch(phase){
   case EffectParticlePhase::Rotation:p.rotation+=p.rotationSpeed*seconds;break;
   case EffectParticlePhase::Acceleration:p.speed=std::max(0.f,p.speed+p.acceleration*seconds);break;
   case EffectParticlePhase::Gravity:p.upwardVelocity-=p.gravity*seconds;break;
   case EffectParticlePhase::Fraction:p.animationFraction=p.durationBound?std::clamp(1-p.durationRemaining/p.duration,0.f,1.f):std::clamp(p.frame/28.f,0.f,1.f);break;
   case EffectParticlePhase::Heading:{const float amount=p.headingSpeed*seconds;if(amount!=0){p.heading+=amount;const float tau=std::bit_cast<float>(0x40c90fdbu);p.heading-=std::floor(p.heading/tau)*tau;}p.headingSpeed+=p.headingAcceleration*seconds;break;}
   case EffectParticlePhase::UpwardVelocity:p.baseZ+=p.upwardVelocity*seconds;break;
   case EffectParticlePhase::PlaySpeed:if(p.book)p.frame+=p.playSpeed*seconds;break;
   case EffectParticlePhase::Translation:{const float distance=p.speed*seconds;p.x+=std::cos(p.heading)*distance;p.y-=std::sin(p.heading)*distance;break;}
   case EffectParticlePhase::BookUpdateInternal:if(p.book){if(p.durationBound&&p.durationRemaining<0){p.done=true;if(p.sound){if(!p.stopSound(p.sound,field(p.sourceDefinition,"StopSoundOnFinishFade"),error))throw std::runtime_error(error);p.sound=0;}}else if(p.loopFramesOnly){if(p.frame>=field(p.sourceDefinition,"EndFrame")+1)p.frame=field(p.sourceDefinition,"StartFrame",1);}else if(p.frame>=29)p.done=true;}break;
   case EffectParticlePhase::SlideUpdateInternal:if(!p.book&&!p.constant){p.slideRemaining-=seconds;if(p.slidesFinished)p.done=true;}break;
   case EffectParticlePhase::SlidePostUpdate:if(!p.book&&!p.constant&&p.slideRemaining<.0001f){if(p.frame>=28)p.slidesFinished=true;else{p.frame+=1;if(!startSlide(p,random,error))throw std::runtime_error(error);}}break;
   case EffectParticlePhase::TimeRemaining:if(p.durationBound)p.durationRemaining-=seconds;break;
   case EffectParticlePhase::ConstantUpdateInternal:if(p.constant&&p.durationRemaining<0)p.done=true;break;
  }}mutating_=false;return true;
 }catch(const std::exception& ex){if(mutating_){faulted_=true;fault_="Original particle phase failed after mutation: "+std::string(ex.what());error=fault_;}else error=ex.what();mutating_=false;return false;}
}
